def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_x_squared(x):
    if x == 1:
        # x^2 = 1, tau(1) = 1
        return 1
    factors = prime_factorization(x)
    # If x = p1^a1 * p2^a2 * ..., then x^2 = p1^(2*a1) * p2^(2*a2) * ...
    # tau(x^2) = (2*a1 + 1) * (2*a2 + 1) * ...
    tau = 1
    for p, a in factors.items():
        tau *= (2 * a + 1)
    return tau

