def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_x(x):
    if x == 1:
        return 1
    factors = prime_factorization(x)
    # tau(x) = (a1 + 1) * (a2 + 1) * ...
    tau = 1
    for a in factors.values():
        tau *= (a + 1)
    return tau

